  "title": "Diff review",
  "version": "0.1.0",
  "publishedAt": "2026-05-09T14:22:18Z",
  "description": "Surface the accumulated patch as a reviewable diff and persist the accept / reject decision.",
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/atoms/diff-review",
  "tags": [
    "atom",
    "first-party",
    "code-migration",
    "tune-collab",
    "phase-7"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "atom",
    "scenario": "code-migration",
    "mode": "review",
    "capabilities": [
      "prompt:inject",
      "fs:read",
      "fs:write"
    ]
  }
}
